System.assertEquals(true, (Boolean)Wave.Templates.getTemplates().get('local'));
System.assertEquals(true, (Boolean)Wave.Templates.getTemplates(new Wave.TemplatesSearchOptions()).get('local'));
System.assertEquals(true, (Boolean)Wave.Templates.getTemplate('Template').get('local'));
System.assertEquals(true, (Boolean)Wave.Templates.getTemplateConfig('Template').get('local'));
System.assertEquals(true, (Boolean)wave.Templates.cdpQueryMetadata('entityType', 'category', 'name', 'default').get('local'));
System.assertEquals(true, (Boolean)wave.Templates.getSObject('Account').get('local'));
System.assertEquals(0, wave.Templates.getSObjects().size());
System.assertEquals(true, (Boolean)wave.Templates.getTemplate('Template', 'App', 'default').get('local'));
System.assertEquals(true, (Boolean)wave.Templates.getTemplateConfig('Template', 'App', true, 'default').get('local'));
System.assertEquals('wave.InvalidParameterException', new wave.InvalidParameterException().getTypeName());
System.assertEquals('wave.WaveQueryException', new wave.WaveQueryException().getTypeName());
wave.ProjectionNode amount = wave.QueryBuilder.get('Amount').sum().alias('total');
System.assertEquals('sum(Amount) as total', amount.build());
System.assertEquals('avg(AccountId)', wave.QueryBuilder.get('AccountId').avg().build());
System.assertEquals('count(AccountId)', wave.QueryBuilder.get('AccountId').count().build());
System.assertEquals('max(AccountId)', wave.QueryBuilder.get('AccountId').max().build());
System.assertEquals('min(AccountId)', wave.QueryBuilder.get('AccountId').min().build());
System.assertEquals('unique(AccountId)', wave.QueryBuilder.get('AccountId').unique().build());
System.assertEquals('count', wave.QueryBuilder.count().build());
wave.QueryNode query = wave.QueryBuilder.load('dataset', 'v1').filter('Amount > 0').filter(new List<String>{'Stage == ClosedWon'}).group().group(new List<String>{'AccountId'}).foreach(new List<wave.ProjectionNode>{amount}).order(new List<List<String>>{new List<String>{'total', 'desc'}}).cap(10);
String built = query.build('q');
System.assert(built.contains('q'));
System.assert(built.contains('load'));
System.assert(built.contains('dataset'));
System.assert(built.contains('filter'));
System.assert(built.contains('group'));
System.assert(built.contains('foreach'));
System.assert(built.contains('order'));
System.assert(built.contains('cap'));
wave.QueryNode byName = wave.QueryBuilder.loadByDeveloperName('pkg.Dataset').filter(new List<String>{'A == 1', 'B == 2'});
System.assert(byName.build('named').contains('pkg.Dataset'));
System.assert(wave.QueryBuilder.union(new List<wave.QueryNode>{query, byName}).build('u').contains('union'));
System.assert(wave.QueryBuilder.cogroup(new List<wave.QueryNode>{query}, new List<List<String>>{new List<String>{'AccountId'}}).build('c').contains('cogroup'));

